-- Restore the remaining English base item descriptions. Locales are unchanged.
-- Six items have no English flavor text; remove their foreign-only description.
-- Keep exact previous bytes as a guard and English replacements readable.
CREATE TEMPORARY TABLE `item_english_remaining_fix` (
  `entry` INT UNSIGNED NOT NULL PRIMARY KEY,
  `old_description` TEXT CHARACTER SET utf8mb4 NOT NULL,
  `new_description` TEXT CHARACTER SET utf8mb4 NOT NULL
);
